DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['test_ph_requests_completed_history','test_ph_chat_messages','test_ph_requests_pending','test_ph_reserves','test_ph_soc_master','test_ph_chat_conversations','test_ph_chat_participants','test_ph_walkie_channels','test_ph_walkie_channel_members','test_ph_walkie_calls','test_ph_walkie_call_members','test_ph_walkie_signal_events','test_ph_app_live_events','test_ph_department_calendar_events','test_ph_warehouse_assigned_items','test_ph_sales_credit_requests','test_ph_eval_work','test_ph_item_inquiry_coverage','test_app_dataset_revisions','test_ph_inventory_row_assignments','test_ph_location_sales_notes','test_ph_pullers','test_ph_wingding_units','test_ph_order_pulling_teams','test_ph_dock_drop_status','test_ph_mistake_queue','test_ph_hl_staging'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename=n) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I',n);END IF;END LOOP;END $$;
